@@ -100,7 +119,10 @@ class ExtensionScriptParent {
     scripts.delete(this);

     this.destroyed = true;
-    this.context.forgetOnClose(this);
+    if (this._parentContext) {
+      this._parentContext.forgetOnClose(this);
